define(['core/ajax'], function(Ajax) {

    var resolveElement = function(selector) {
        if (!selector) {
            return null;
        }
        if (typeof selector !== 'string') {
            // A jQuery object or array-like collection.
            return selector.length ? selector[0] : selector;
        }
        return document.getElementById(selector) || document.querySelector(selector);
    };

    return {
        transport: function(selector, query, success, failure) {
            var el = resolveElement(selector);
            var categoryid = el ? el.getAttribute('data-categoryid') : 0;

            if (!categoryid) {
                failure('Vikesa course wizard: could not resolve the category for this picker.');
                return;
            }

            Ajax.call([{
                methodname: 'local_vikesa_coursewizard_search_users',
                args: {categoryid: parseInt(categoryid, 10), query: query}
            }])[0].then(success).catch(failure);
        },
        processResults: function(selector, results) {
            return results.map(function(r) {
                return {value: r.id, label: r.fullname};
            });
        }
    };
});
